FROM platform_call_minute WHERE bucket_start >= #{from} AND bucket_start < #{to} AND mode=#{mode}
AND api_key=#{apiId}
AND application_key=#{applicationId}

FROM platform_rule_minuteplatform_call_minute
WHERE bucket_start >= #{from} AND bucket_start < #{to} AND mode=#{q.mode}
AND api_key=#{q.apiId}
AND application_key=#{q.applicationId}
AND tenant_key=#{q.tenantId}
AND employee_key=#{q.employeeId}
AND identity_kind=#{q.identityKind}
AND rule_id=#{q.ruleId} AND rule_version=#{q.ruleVersion}

mapper.select:
SELECT rule_id,rule_version, FROM platform_rule_minute
WHERE bucket_start >= #{from} AND bucket_start < #{to} AND mode=#{mode}
    AND rule_id IN #{id}
GROUP BY rule_id,rule_version
